import { schoolWords,deckWords,schoolCounts } from './school_word_data.mjs';
import { createWordProgress } from './school_word_progress.mjs';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const progress=createWordProgress(schoolWords);
let deck='elementary',mode='learn',filter='all',search='',category='全部',index=0,revealed=false,feedback=null,queue=null,showHint=false;
export const normalizeSpelling=s=>s.trim().toLowerCase().replace(/[’‘]/g,"'").replace(/\s+/g,' ');
export function meaningChoices(card,pool){const unique=[...new Set(pool.filter(w=>w.id!==card.id&&!card.meanings.includes(w.zh)).map(w=>w.zh))];const candidates=[card.zh,...unique.slice(0,3)];const shift=[...card.word].reduce((n,c)=>n+c.charCodeAt(0),0)%candidates.length;return [...candidates.slice(shift),...candidates.slice(0,shift)];}
function matches(){return deckWords(deck).filter(c=>(category==='全部'||c.category===category)&&`${c.word} ${c.meanings.join(' ')}`.toLowerCase().includes(search.toLowerCase())&&(filter==='new'?!progress.get(c.id):filter==='due'?progress.isDue(c.id):true));}
function reset(){index=0;revealed=false;feedback=null;queue=null;showHint=false;}
function active(){if(!queue)queue=matches().map(c=>c.id);return schoolWords.find(c=>c.id===queue[index]);}
export function renderSchoolWords(){
 const words=deckWords(deck), c=active(),due=words.filter(w=>progress.isDue(w.id)).length,fresh=words.filter(w=>!progress.get(w.id)).length;
 const categories=[...new Set(words.map(w=>w.category))];
 const stat=c?progress.get(c.id):null;
 const masteredCount=words.filter(w=>{const s=progress.get(w.id);return s&&s.step>=3;}).length;
 const progressPct=words.length?Math.round((masteredCount/words.length)*100):0;

 return `<article class="lesson-page school-words"><header><p class="pill">🗂️ 國小・國中單字卡</p><h1>先回想，再翻卡，隔天再確認</h1><p>國小 ${schoolCounts.elementary} 張；國中 ${schoolCounts.junior} 張（含國小複習）。整合本網站課程字彙與補充教材，提供例句與間隔複習。到期後答對才會延長間隔；提前練習不會跳級。</p><div style="background:#e2e8f0;height:8px;border-radius:4px;overflow:hidden;margin:12px 0 6px"><div style="background:#10b981;height:100%;width:${progressPct}%;transition:width 0.3s ease"></div></div><p class="small" style="color:#64748b;margin:0 0 16px">複習排程達第 3 階以上（含舊紀錄）： ${masteredCount} / ${words.length} 詞 (${progressPct}%)</p></header>
 <div class="word-controls"><label>卡庫<select data-word-setting="deck"><option value="elementary" ${deck==='elementary'?'selected':''}>國小基礎 (${schoolCounts.elementary} 張)</option><option value="junior" ${deck==='junior'?'selected':''}>國中＋基礎複習 (${schoolCounts.junior} 張)</option></select></label><label>練習方式<select data-word-setting="mode">${[['learn','翻卡記憶'],['meaning','選出字義'],['spell','看中文拼英文']].map(([id,label])=>`<option value="${id}" ${mode===id?'selected':''}>${label}</option>`).join('')}</select></label><label>學習清單<select data-word-setting="filter">${[['all','全部'],['due','到期複習'],['new','尚未練習']].map(([id,label])=>`<option value="${id}" ${filter===id?'selected':''}>${label}</option>`).join('')}</select></label><label>主題<select data-word-setting="category"><option>全部</option>${categories.map(x=>`<option ${x===category?'selected':''}>${e(x)}</option>`).join('')}</select></label></div>
 <form class="word-search"><label for="school-word-search">搜尋英文或中文</label><input id="school-word-search" value="${e(search)}" type="search"><button class="btn quiet" type="submit">搜尋</button></form>
 <p role="status">到期 ${due} 張 · 未練習 ${fresh} 張 · 目前清單 ${queue.length} 張</p>
 ${c?`<section class="card word-face"><p class="pill">${e(c.category)} · ${index+1}/${queue.length}</p><h2 lang="${mode==='spell'?'zh-Hant':'en'}">${e(mode==='spell'?c.zh:c.word)}</h2>${mode!=='spell'?`<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:10px 0"><button class="btn quiet" data-speak-word="${e(c.word)}">🔊 標準發音</button><button class="btn quiet" data-speak-word="${e(c.word)}" data-slow="true">🐢 慢速拼讀</button></div>`:''}
 ${mode==='learn'?`<p>先說出中文意思，再試著用這個字造句。</p>${!revealed?'<button class="btn primary" data-word-action="reveal">翻卡：查看意思與例句</button>':''}`:mode==='meaning'?`<fieldset class="lesson-check"><legend>這個字在本卡的意思是？</legend>${meaningChoices(c,words).map((s,i)=>`<button class="btn quiet lesson-option" data-word-choice="${i}" ${feedback?'disabled':''}>${e(s)}</button>`).join('')}</fieldset>`:`<form class="word-spelling"><label for="school-spelling">輸入英文單字或片語</label><input id="school-spelling" autocomplete="off" autocapitalize="none" spellcheck="false" ${feedback?'disabled':''}><div style="display:flex;gap:8px;margin-top:8px"><button class="btn primary" ${feedback?'disabled':''}>檢查拼字</button>${c.word?`<button type="button" class="btn quiet" data-word-action="hint" ${feedback?'disabled':''}>💡 顯示首字母提示</button>`:''}</div>${showHint?`<p style="font-size:13px;color:#0e7490;margin-top:6px">提示：首字母 <strong>${e(c.word[0].toUpperCase())}</strong>，共 ${c.word.length} 個字母</p>`:''}</form>`}
 ${feedback?`<div class="word-feedback" role="status" tabindex="-1"><strong>${feedback.right?'答對':'再練一次'}</strong><p>${e(feedback.text)}</p></div>`:''}
 ${revealed||feedback?`<div class="word-back"><div style="display:flex;align-items:center;gap:12px;margin:8px 0 12px;background:#f8fafc;padding:12px 14px;border-radius:12px;border:1px solid #e2e8f0"><div style="font-size:36px;line-height:1;width:52px;height:52px;border-radius:12px;background:#10b98115;border:1px solid #10b98135;display:flex;align-items:center;justify-content:center;flex-shrink:0">${e(c.icon||'📌')}</div><div style="flex-grow:1"><h3 lang="en" style="margin:0 0 2px;font-size:19px">${e(c.word)} <small style="color:#64748b;font-weight:normal">${e(c.ipa)}</small></h3><div style="display:flex;align-items:center;gap:6px"><span class="pill" style="font-size:11px;background:#e0e7ff;color:#3730a3">${e(c.pos||'n.')}</span><span style="font-size:14px;color:#047857;font-weight:700">釋義：${c.meanings.map(e).join('；')}</span></div></div></div>${c.chunk?`<p style="font-size:13px;color:#0e7490;margin:4px 0">🔤 <strong>拼讀音節：</strong><code>${e(c.chunk)}</code></p>`:''}${c.collocation?`<p style="font-size:13px;color:#1e40af;margin:4px 0">🔗 <strong>常用搭配：</strong>${e(c.collocation)}</p>`:''}${c.example?`<blockquote lang="en" style="margin:10px 0;padding:8px 14px;border-left:3px solid #2563eb;background:#f8fafc">${e(c.example)}</blockquote><div style="display:flex;gap:8px;margin-bottom:8px"><button class="btn quiet small" data-speak-sentence="${e(c.example)}">🔊 朗讀例句</button><button class="btn quiet small" data-speak-sentence="${e(c.example)}" data-slow="true">🐢 慢速例句</button></div>`:''}${c.exampleZh?`<p style="font-size:13px;color:#475569;margin-top:2px">${e(c.exampleZh)}</p>`:''}${c.memoryTip?`<div style="background:#fffbeb;border:1px solid #fde68a;padding:8px 12px;border-radius:6px;font-size:13px;color:#92400e;margin:10px 0">💡 <strong>自然拼讀與記憶要點：</strong>${e(c.memoryTip)}</div>`:''}<p style="font-size:13px;color:#64748b"><strong>記憶做法：</strong>想像例句中的場景，換成自己熟悉的人或地點說一次；再遮住英文，拼寫一次。</p><details><summary>教材來源</summary><ul>${c.sources.map(s=>`<li>${e(s)}</li>`).join('')}</ul></details>${mode==='learn'?`<div class="lesson-links"><button class="btn quiet" data-word-rate="miss">還想不起來 · 10 分鐘後複習</button><button class="btn primary" data-word-rate="remember">遮住後能回想 · 安排下次複習</button></div>`:''}</div>`:''}
 <p class="small">${stat?`累計 ${stat.reviews} 次 · 下次 ${new Date(stat.due).toLocaleString('zh-TW')}`:'尚未記錄。翻卡本身不等於記住。'}</p><button class="btn quiet" data-word-action="next">${index+1<queue.length?'下一張 →':'結束這輪 →'}</button></section>`:'<section class="card"><h2>這輪已完成，或目前沒有符合條件的卡片</h2><p>到期複習只包含時間已到的卡片。可以改選「尚未練習」或其他主題。</p><button class="btn primary" data-word-action="restart">重新整理清單</button></section>'}
 <p id="word-save-status" role="status">${e(progress.warning||'紀錄只存於本瀏覽器。答錯 10 分鐘後再看；記住後依序隔 1、3、7、14、30 天複習。')}</p><details><summary>如何每天練習？</summary><ol><li>先做「到期複習」，每次約 10-20 張。</li><li>再選少量新字，先猜意思才翻卡。</li><li>改用字義與拼字練習，確認能主動回想與正確拼寫。</li></ol><p>這是固定間隔排程，不是已校準的記憶能力模型；自評記住不代表通過測驗。</p></details></article>`;
}
function score(right,text,render){const c=active();if(!c||feedback)return;progress.record(c.id,right);feedback={right,text};render();document.querySelector('.word-feedback')?.focus();}
export function handleSchoolWordClick(button,render){const d=button.dataset;if(d.wordChoice!==undefined){const c=active(),options=c?meaningChoices(c,deckWords(deck)):[],choice=Number(d.wordChoice);if(c&&Number.isInteger(choice)&&choice>=0&&choice<options.length)score(options[choice]===c.zh,`你選：${options[choice]}；${c.word} 在本卡指「${c.zh}」。請用例句核對意思。`,render);return true;}if(d.wordRate){const c=active();if(c&&revealed){progress.record(c.id,d.wordRate==='remember');index++;revealed=false;feedback=null;showHint=false;render();}return true;}if(d.wordAction){if(d.wordAction==='reveal')revealed=true;else if(d.wordAction==='next'){index++;revealed=false;feedback=null;showHint=false;}else if(d.wordAction==='restart')reset();else if(d.wordAction==='hint')showHint=!showHint;render();return true;}return false;}
export function handleSchoolWordChange(target,render){const k=target.dataset.wordSetting;if(!k)return false;if(k==='deck'){deck=target.value==='junior'?'junior':'elementary';category='全部';}if(k==='mode')mode=target.value;if(k==='filter')filter=target.value;if(k==='category')category=target.value;reset();render();return true;}
export function handleSchoolWordSubmit(form,render){if(form.classList.contains('word-search')){search=form.querySelector('input').value.trim();reset();render();return true;}if(form.classList.contains('word-spelling')){const c=active(),value=form.querySelector('input').value;if(c&&!feedback)score(normalizeSpelling(value)===normalizeSpelling(c.word),`你的拼字：${value||'（空白）'}；正確拼字：${c.word}。`,render);return true;}return false;}
